"""
Generates a modm `Board::SystemClock` struct for a configuration, against the
Rcc API rendered for the device (see `modm_api`), so only existing setters and
enumerators come out. Anything the API cannot express becomes a TODO comment.
"""

import re

from jinja2 import Environment

from .solver import choice_of

# Laid out like the modm BSPs: namespace Board, unindented
_TEMPLATE = """\
namespace Board
{
using namespace modm::literals;

/// {{ device }}, generated by the clock solver for the modm Rcc API
struct SystemClock
{
{% for name, value in frequencies %}
\tstatic constexpr uint32_t {{ name.ljust(pad) }} = {{ value ~ ";" if value else "0; // no clock" }}
{% endfor %}
{% for c in constants %}
{% if loop.first %}

{% endif %}
{% if c.comment %}
\t{{ c.comment }}
{% endif %}
\tstatic constexpr Rcc::{{ c.type }} {{ c.name }}{
{% for field in c.fields %}
\t\t{{ field }}{{ "," if not loop.last }}
{% endfor %}
\t};
{% endfor %}

\tstatic bool inline
\tenable()
\t{
{% for line in calls %}
\t\t{{ line }}
{% endfor %}
{% for todo in todos %}
\t\t// TODO: {{ todo }}
{% endfor %}
\t\treturn true;
\t}
};
{% if flash %}
// flash: {{ flash }}{{ ", " ~ scale if scale }}
{% endif %}

} // namespace Board
"""


def unit(f: float) -> str:
    """A modm frequency literal: 8_MHz, 12.288_MHz, 32.768_kHz, 100_Hz, decimals only where they are exact."""
    n = round(f)
    for scale, suffix in ((1_000_000, "_MHz"), (1_000, "_kHz")):
        if n < scale:
            continue
        text = f"{n / scale:.10g}"
        if "e" not in text and int(float(text) * scale) == n:
            return text + suffix
    return f"{n}_Hz"


def _g(value) -> str:
    """A setting as C++ text: 2 not 2.0, macros as they are."""
    return f"{value:g}" if isinstance(value, (int, float)) else str(value)


def _norm(s: str) -> str:
    s = re.sub(r"[^a-z0-9]", "", s.lower()).replace("lptimer", "lptim").replace("timer", "tim")
    # setDfsdm1KernelClock and setDfsdm1AudioClock are the DFSDMMult and DFSDMAudioMult
    s = re.sub(r"dfsdm\d?(kernel)?", "dfsdm", s)
    s = re.sub(r"fdcan\d?", "fdcan", s.replace("sdmmc12", "sdmmc")).replace("usart", "uart").replace("quadspi", "qspi")
    # Sai1BlockA and SAI_A are the same SAI block
    return re.sub(r"sai\d?(?:block)?([ab])$", r"sai\1", s)


def candidates(src: str, signal: str = "") -> list[str]:
    """The modm enumerator names a CubeMX clock source may have, from modm-hardware-ci clockmeter/gen.py."""
    s, g = src.upper(), signal.upper()
    # PLLRoutput is PLLR
    s = re.sub(r"(?<=[PQR])OUTPUT$", "", s)
    if re.search(r"I2S_?CKIN|AUDIOCLK|SAI\d?_EXT", s + " " + g):
        return ["External", "Pin", "AudioClk", "I2sCkin", "I2sCkIn", "ExtClk"]
    # The H7R/S ETH1 reference clock: the RMII pin or the PHY clock fed back
    if s == "DIG_CKIN":
        return ["RmiiRefClk"]
    if s == "ETHPHYMULT":
        return ["EthClkFb"]
    if s.startswith("RTCWKUP"):
        return ["RtcWakeup"]
    if s.startswith("RTCCLK"):
        return ["Rtc"]
    if s.startswith("SPDIF"):
        return ["SpdifSymbol", "Spdif"]
    if re.fullmatch(r"\w*CSIDE?VISOR", s):
        return ["CsiDiv122", "Csi"]
    # The H7 HRTIM runs from the timer clock or the CPU clock
    if s == "TIM2OUTPUT":
        return ["Timer"]
    if s == "D1CPRE":
        return ["Cpu"]
    # The L4+/U3 DFSDM audio clock and the U3 ADF take the SAI1 clock
    if m := re.fullmatch(r"SAI(\d)(MULT|OUTPUT)", s):
        return [f"Sai{m[1]}"]
    if re.fullmatch(r"(AHB\d?|HCLK\d?)OUTPUT", s):
        return ["Hclk", "Ahb", "Hclk3", "Bus"]
    # The HAL2 HCLK, which the STM32G5 calls bus_ck = rcc_tim_ker_ck in the ADC mux
    if s in ("HPRE", "BMPRE", "HCLK_FREQUENCY", "AHB_CLOCK"):
        return ["Hclk", "Ahb", "Bus", "Tim"]
    if s.startswith("HSERTC"):
        return ["HseDiv32", "HseDiv", "Hse"]
    if s == "USBPHYRC" or s.startswith("DSIPHY"):
        return ["UsbPhy", "DsiPhy"]
    if s == "TIMMUL":
        return ["Pll"]
    if s == "PLLSOURCE":
        return ["PllSource", "PllInput"]
    if m := re.fullmatch(r"DIV([PQRST])(\d)", s):
        return [f"Pll{m[2]}{m[1]}"]
    if m := re.fullmatch(r"PLL(\d?)([PQR])", s):
        return [f"Pll{m[1]}{m[2]}"] + ([] if m[1] else [f"Pll1{m[2]}", f"MainPll{m[2]}", "Pll"])
    if m := re.fullmatch(r"PLLSAI(\d?)([PQR])", s):
        return [f"PllSai{m[1]}{m[2]}"] + ([] if m[1] else ["PllSai"])
    if m := re.fullmatch(r"PLL(I2S|SAI)\w*DIV", s):
        # The divider behind a PLL output, the F4 PLLI2SSAIDiv after PLLI2SQ
        pll = "PllI2s" if m[1] == "I2S" else "PllSai"
        return [pll, pll + "Q", pll + "R"]
    if m := re.fullmatch(r"PLLI2S([PQR])", s):
        return [f"PllI2s{m[1]}", "PllI2s"]
    if s == "HSISYS":
        return ["HsiSys", "Hsi"]
    # The HAL2 dividers in front of a source, the STM32C5 HSI_DIV_3 and PSI_DIV_3
    if m := re.fullmatch(r"(HSI|HSE|PSI)_?DIV_?(\d+)", s):
        return [f"{m[1].capitalize()}Div{m[2]}"]
    if s in ("PSI", "PSIK", "HSIK"):
        return {"PSI": ["Psi", "Psis"], "PSIK": ["Psik"], "HSIK": ["Hsik"]}[s]
    if s in ("PLLMUL", "PLLCLK", "PLLDIV"):
        return ["Pll", "PllR", "Pll1R"]
    if s == "MCOMULTDIVISOR":
        return ["PllDiv2", "Pll"]
    if "PCLK" in g or re.match(r"(APB\d?|D\dPPRE\d?|CDPPRE\d?|SRDPPRE|PPRE\d|TIMPRESC)", s) or "PRESCALER" in s:
        return ["Bus", "Pclk", "Pclk1", "Pclk2", "Pclk3", "Apb", "Apb1", "Apb2", "Apb3", "Apb4"]
    if "SYSCLK" in s or "SYSCLK" in g:
        return ["SysClk", "Sysclk", "System", "SystemClock"]
    if re.search(r"(CK|CLK|PLL)48", s) or s == "USBMULT":
        # The 48 MHz mux output that SDIO, SDMMC and RNG take
        return ["Clk48", "Clock48", "Pll48", "Iclk"]
    if s in ("HSI48RC", "RC48", "HSIRC48", "HSIUSB48", "HSI48"):
        return ["Hsi48", "HsiUsb48"]
    for prefix, names in (
        ("HSIKER", ["HsiKer", "Hsi"]),
        ("HSI", ["Hsi", "Hsi16", "HsiKer", "HsiSys"]),
        ("LSE", ["Lse"]),
        ("LSI", ["Lsi"]),
        ("CSI", ["Csi"]),
        ("HSE", ["Hse", "HseDiv2"]),
        ("MSIK", ["MsiK", "Msik"]),
        ("MSIS", ["MsiS", "Msi"]),
        ("MSI", ["Msi", "MsiS"]),
    ):
        if s.startswith(prefix):
            return names
    if re.search(r"AUDIOCLK|I2S_?CKIN", s + " " + g):
        return ["AudioClk", "I2sCkin", "I2sCkIn", "Pin"]
    if "PER" in s:
        return ["Per", "PerClk", "PerCk"]
    return []


# The CubeMX names, then those of the HAL2 trees
_PRESCALERS = {
    "setAhbPrescaler": ["AHBPrescaler", "HPRE", "BMPRE", "AHB_Clock_Divider"],
    "setApbPrescaler": ["APBPrescaler"],
    "setApb1Prescaler": ["APB1Prescaler", "D2PPRE1", "APB1_Clock_Divider"],
    "setApb2Prescaler": ["APB2Prescaler", "D2PPRE2", "APB2_Clock_Divider"],
    "setApb3Prescaler": ["APB3Prescaler", "D1PPRE", "APB3_Clock_Divider"],
    "setApb4Prescaler": ["D3PPRE", "APB4_Clock_Divider"],
    "setCpuPrescaler": ["D1CPRE", "CPRE"],
}
_SYSTEM_MUX = ["SysClkSource", "System_Clock_Source"]


def _pll(fn, n, m, p, q, r, frac=(), src=(), s=()):
    return {"fn": fn, "n": n, "m": m, "p": p, "q": q, "r": r, "frac": frac, "src": src, "s": s}


_PLLS = [
    _pll(["enablePll", "enablePll1"], ["PLLN", "DIVN1", "PLL1N", "PLLMUL"], ["PLLM", "DIVM1", "PLL1M"],
         ["PLLP", "DIVP1", "PLL1P"], ["PLLQ", "DIVQ1", "PLL1Q"], ["PLLR", "DIVR1", "PLL1R"],
         ["PLLFRACN", "FRACN1", "PLL1FRACN"], ["PLLSource", "PLL1Source", "PLL1_Clock_Source", "PLL_Clock_Source"],
         ["DIVS1"]),
    _pll(["enablePll2"], ["PLL2N", "DIVN2"], ["PLL2M", "DIVM2"], ["PLL2P", "DIVP2"], ["PLL2Q", "DIVQ2"],
         ["PLL2R", "DIVR2"], ["PLL2FRACN", "FRACN2"], ["PLL2Source", "PLLSource", "PLL2_Clock_Source", "PLL_Clock_Source"],
         ["DIVS2"]),
    _pll(["enablePll3"], ["PLL3N", "DIVN3"], ["PLL3M", "DIVM3"], ["PLL3P", "DIVP3"], ["PLL3Q", "DIVQ3"],
         ["PLL3R", "DIVR3"], ["PLL3FRACN", "FRACN3"], ["PLL3Source", "PLLSource", "PLL_Clock_Source"], ["DIVS3"]),
    _pll(["enablePllSai1"], ["PLLSAI1N"], ["PLLSAI1M"], ["PLLSAI1P"], ["PLLSAI1Q"], ["PLLSAI1R"], src=["PLLSAI1Source"]),
    _pll(["enablePllSai2"], ["PLLSAI2N"], ["PLLSAI2M"], ["PLLSAI2P"], ["PLLSAI2Q"], ["PLLSAI2R"], src=["PLLSAI2Source"]),
    _pll(["enablePllSai"], ["PLLSAIN"], ["PLLSAIM"], ["PLLSAIP"], ["PLLSAIQ"], ["PLLSAIR"]),
    _pll(["enablePllI2s"], ["PLLI2SN"], ["PLLI2SM"], ["PLLI2SP"], ["PLLI2SQ"], ["PLLI2SR"]),
]  # fmt: skip


# The dividers between a PLL output and its peripherals, the F4/F7 LTDC and SAI clocks
_POST_DIVIDERS = (
    ("PLLSAILCDDiv", "setPllSaiDivR"),
    ("PLLSAISAIDiv", "setPllSaiDivQ"),
    ("PLLI2SSAIDiv", "setPllI2sDivQ"),
)


def modm_name(p: str) -> str:
    """modm names of the kernel clock constants: Usart1, Timer1, LpUart1, UsbOtgFS, ..."""
    s = p.lower()
    for a, b in (
        ("lptim", "LpTimer"),
        ("tim", "Timer"),
        ("lpuart", "LpUart"),
        ("fdcan", "FdCan"),
        ("octospi", "OctoSpi"),
    ):
        if s.startswith(a):
            s = b + s[len(a) :]
            break
    if m := re.match(r"usb_otg_(fs|hs)(.*)", s):
        s = "UsbOtg" + m[1].upper() + m[2]
    s = s[0].upper() + s[1:]
    return re.sub(r"_(\w)", lambda m: m[1].upper(), s)


class _Writer:
    def __init__(self, tree, api, config, result):
        self.tree, self.api, self.config, self.result = tree, api, config, result
        self.nodes = tree["nodes"]
        self.lines, self.todo, self.consts = [], [], []

    def get(self, name):
        return choice_of(self.tree, name, self.config)

    def used(self, name) -> bool:
        return bool(self.result.get(name, {}).get("used"))

    def freq(self, name):
        return self.result.get(name, {}).get("freq")

    def has(self, fn) -> bool:
        return fn in self.api["functions"]

    def enum_of(self, fn, arg=0):
        params = [p.strip().split(" ")[0] for p in self.api["functions"].get(fn, "").split(",")]
        params = [re.sub(r"^const$", "", p) for p in params]
        if arg < len(params) and params[arg]:
            # "const PllConfig& x" keeps the type as the second word
            return params[arg]
        return None

    def value(self, enum, names):
        values = [e[0] for e in self.api["enums"].get(enum, ())]
        if found := next((n for n in names if n in values), None):
            return found
        # A divided source like HsiDiv488 for HSIDivCEC, only when it is the one with that stem
        for n in names[:1]:
            longer = [v for v in values if v.startswith(n + "Div")]
            if len(longer) == 1:
                return longer[0]
        return None

    def input(self, name):
        now = self.get(name)
        return next((i for i in self.nodes.get(name, {}).get("inputs", ()) if now in (i.get("macro"), i["from"])), None)

    def source_value(self, enum, name):
        """The enumerator for the selected input of a mux, through dividers in front of a source too."""
        input = self.input(name)
        if not input:
            return None
        names = candidates(input["from"], input.get("signal", ""))
        # F1 HSIDivPLL / HSEDivPLL: a fixed or chosen /2 in front of the PLL
        node = self.nodes.get(input["from"])
        if (
            node
            and node["kind"] == "div"
            and re.fullmatch(r"(HSI|HSE)Div(PLL)?", input["from"])
            and "HsiSys" not in enum
        ):
            cap = input["from"][0] + input["from"][1:3].lower()
            names = [f"{cap}Div2", cap] if self.get(input["from"]) == 2 else [cap, f"{cap}Div2"]
        return self.value(enum, names)

    def call(self, fn, *args):
        self.lines.append(f"Rcc::{fn}({', '.join(args)});")


def _derive(w: _Writer, name: str, named: dict):
    """
    The constant as an earlier one: the nearest named node upstream through the selected inputs,
    when the frequency is that one times or divided by a whole number (Apb2 = Ahb / 2, Usart1 = Apb2).
    """
    f, seen, x = w.freq(name), set(), name
    while x and x not in seen:
        seen.add(x)
        node = w.nodes.get(x)
        if x != name and x in named:
            g = w.freq(x)
            if not g:
                return None
            if abs(f - g) < 0.5:
                return named[x]
            if abs(g / f - round(g / f)) < 1e-9:
                return f"{named[x]} / {round(g / f)}"
            if abs(f / g - round(f / g)) < 1e-9:
                return f"{named[x]} * {round(f / g)}"
            return None
        # A PLL output is its own number, Hse * 3 through a VCO says nothing
        if not node or not node["inputs"] or re.search(r"PLL|^DIV[MNPQR]\d?$|VCO|FRAC", x, re.I):
            return None
        pick = choice_of(w.tree, x, w.config) if node["kind"] == "mux" else None
        x = next(
            (i for i in node["inputs"] if pick is not None and (i.get("macro") or i["from"]) == pick), node["inputs"][0]
        )["from"]
    return None


def _pick_setter(w: _Writer, name: str, setters: list):
    """The setter of a kernel clock mux, by the peripherals it clocks and by its own name."""
    n = w.nodes
    # The HAL2 trees name them FDCAN_Clock_Source
    stem = _norm(
        re.sub(r"(Mult|MuxSrc|Mux|CLockSelection|ClkSource|_Clock_Source|Source|Selection)$", "", name, flags=re.I)
    )
    peripherals, stack = set(), list(n[name]["outputs"])
    while stack:
        x = stack.pop()
        if x not in n or n[x]["kind"] == "mux":
            continue
        if n[x]["kind"] == "peripheral":
            peripherals.add(_norm(x))
        else:
            stack += n[x]["outputs"]
    special = {"rtc": "setRealTimeClockSource", "ck48": "setClk48Source", "clk48": "setClk48Source",
               "mco1": "setMco1ClockSource", "mco": "setMcoClockSource", "mco2": "setMco2ClockSource",
               "ckper": "setPerClockSource", "lsco": "setLscoClockSource", "fdcan": "setCanClockSource",
               "eth1": "setEthRefClockSource"}  # fmt: skip
    if special.get(stem) in setters:
        return special[stem]
    # The 48 MHz mux of USB, RNG and SDIO: CubeMX names it after USB, modm after the clock
    # The H723 and H7A3 CubeMX name their OCTOSPI mux QSPIMult
    if stem == "qspi" and "setOctoSpiClockSource" in setters and "setQuadSpiClockSource" not in setters:
        return "setOctoSpiClockSource"
    # The F446 SAI1 and SAI2 muxes are SAIAMult and SAIBMult
    if (m := re.fullmatch(r"sai([ab])", stem)) and not any(re.search(r"Sai\d?[AB]", s) for s in setters):
        if (fn := f"setSai{'12'[m[1] == 'b']}ClockSource") in setters:
            return fn
    # The U0 RNG takes the 48 MHz clock
    if stem in ("usb", "ck48", "clk48", "pll48", "usbotg") or (stem == "rng" and not any("Rng" in s for s in setters)):
        for name in ("setClk48Source", "setClock48Source", "setUsbClockSource"):
            if name in setters:
                return name
    if stem == "mco" and "setMco1ClockSource" in setters:
        return "setMco1ClockSource"
    best, score = None, 0
    for s in setters:
        key = _norm(re.sub(r"(ClockSource|Source|Clock)$", "", s[3:]))
        # setTim34ClockSource clocks TIM3 and TIM4
        group = {m[1] + d for d in m[2]} if (m := re.fullmatch(r"([a-z]+)(\d{2,})", key)) else set()
        k = 4 if key in peripherals or group & peripherals else 3 if key == stem else 0
        if not k and key.startswith(stem) and len(stem) > 2:
            k = 2
        elif not k and stem.startswith(key) and len(key) > 2:
            k = 1
        if k > score:
            best, score = s, k
    return best


def system_clock(tree: dict, device: str, config: dict, result: dict, use, api: dict) -> dict:
    """
    The content of the `SystemClock` struct, which `generate` renders: the frequency constants with their
    expressions, the PLL and PSI configurations, the Rcc calls of `enable()` and what modm cannot express.
    """
    w, n = _Writer(tree, api, config, result), tree["nodes"]

    def first(names):
        return next((x for x in names if x in n), None)

    def mode(name):
        return str(config.get(name, "")).lower()

    # ---- sources
    if w.used("HSEOSC"):
        w.call("enableHseClock" if mode("HSE") == "bypass" and w.has("enableHseClock") else "enableHseCrystal")
    if "HSIRC" in n and w.used("HSIRC") and w.has("enableHsiClock"):
        params = api["functions"]["enableHsiClock"]
        if "HsiSysPrescaler" in params and "HSISYS" in n:
            ker = next((x for x in ("HSIKER", "HSIKERDiv") if x in n), None)
            w.call(
                "enableHsiClock", f"Rcc::HsiSysPrescaler::Div{_g(w.get('HSISYS'))}", *([_g(w.get(ker))] if ker else [])
            )
        elif "HsiPrescaler" in params and "HSISYS" in n and w.get("HSISYS") != 1:
            w.call("enableHsiClock", f"Rcc::HsiPrescaler::Div{_g(w.get('HSISYS'))}")
        elif re.search(r"HsiDivider|HsiPrescaler", params) and "HSIDiv" in n and w.get("HSIDiv") != 1:
            w.call("enableHsiClock", f"Rcc::{w.enum_of('enableHsiClock')}::Div{_g(w.get('HSIDiv'))}")
        else:
            w.call("enableHsiClock")
        # The STM32G5 HSI divider, which the system clock and the PLLs take
        if "HSIDIV" in n and w.get("HSIDIV") != 1:
            if w.has("setHsiDivider"):
                w.call("setHsiDivider", f"Rcc::{w.enum_of('setHsiDivider')}::Div{_g(w.get('HSIDIV'))}")
            else:
                w.todo.append(f"HSI /{_g(w.get('HSIDIV'))}: no setHsiDivider()")
    # The STM32C5 HSI runs at 144 MHz, its HSIDIV3 and HSIK outputs are enabled on their own
    if "HSI_DIV_3" in n and w.used("HSI_DIV_3") and w.has("enableHsiDiv3Clock"):
        w.call("enableHsiDiv3Clock")
    if "HSIK" in n and w.used("HSIK") and w.has("enableHsiKernelClock"):
        w.call(
            "enableHsiKernelClock",
            f"Rcc::{w.enum_of('enableHsiKernelClock')}::Div{_g(w.get('HSIK')).replace('.', '_')}",
        )
    for x in ("HSI48RC", "HSI48", "RC48", "HSIRC48", "HSIUSB48", "HSIUSB48RC"):
        if x in n and w.used(x):
            fn = next((f for f in ("enableHsi48Clock", "enableHsiUsb48Clock") if w.has(f)), None)
            w.call(fn) if fn else w.todo.append(f"enable {x}")
    if "CSIRC" in n and w.used("CSIRC"):
        w.call("enableCsiClock") if w.has("enableCsiClock") else w.todo.append("enable CSI")
    if "MSIRC" in n and w.used("MSIRC"):
        f = w.freq("MSIRC")
        name = f"MHz{f / 1e6:.3f}".rstrip("0").rstrip(".").replace(".", "_") if f >= 1e6 else f"kHz{round(f / 1e3)}"
        fn = next((x for x in ("enableMsiClock", "enableMsiSystemClock") if w.has(x)), None)
        e = fn and w.enum_of(fn)
        if e and w.value(e, [name]):
            w.call(fn, f"Rcc::{e}::{name}")
        else:
            w.todo.append(f"MSI at {f:g} Hz: no modm {e or 'MSI'} enumerator {name}")
    if "MSIKRC" in n and w.used("MSIKRC") and w.has("enableMsiKernelClock"):
        f = w.freq("MSIKRC")
        name = f"MHz{f / 1e6:.3f}".rstrip("0").rstrip(".").replace(".", "_")
        e = w.enum_of("enableMsiKernelClock")
        w.call("enableMsiKernelClock", f"Rcc::{e}::{name}") if w.value(e, [name]) else w.todo.append(
            f"MSIK at {f:g} Hz"
        )
    if "LSEOSC" in n and w.used("LSEOSC"):
        w.call("enableLseClock" if mode("LSE") == "bypass" and w.has("enableLseClock") else "enableLseCrystal")
    if "LSIRC" in n and w.used("LSIRC"):
        w.call("enableLsiClock")

    # ---- voltage scale and flash
    options = result.get("options", {}).get("setting", {})
    scale = options.get("PWR_Regulator_Voltage_Scale")
    if scale and w.has("setVoltageScaling"):
        e = w.enum_of("setVoltageScaling")
        num = (m := re.search(r"SCALE(\d)", scale)) and m[1]
        if "BOOST" in scale:
            value = w.value(e, ["Boost", "Range1Boost"])
        else:
            value = w.value(e, [f"Scale{num}", f"Range{num}", *{"0": ["High"], "1": ["Low"]}.get(num, [])])
        w.call("setVoltageScaling", f"Rcc::{e}::{value}") if value else w.todo.append(f"voltage scale {scale}")
    elif scale and not scale.endswith("SCALE1"):
        w.todo.append(f"voltage scale {scale}: no setVoltageScaling()")
    if options.get("PWREXT_OverDrive", "").endswith("_ACTIVATED"):
        w.call("enableOverdriveMode") if w.has("enableOverdriveMode") else w.todo.append("over-drive")
    # The flash runs on HCLK, which is less than the CPU clock on the H7
    w.lines.append(f"Rcc::setFlashLatency<{'Ahb' if 'AHBOutput' in n else 'Frequency'}>();")

    # ---- prescalers before the system clock speeds up
    for fn, names in _PRESCALERS.items():
        if not (x := first(names)):
            continue
        if not w.has(fn):
            if w.get(x) != 1:
                w.todo.append(f"{x} /{_g(w.get(x))}: no {fn}()")
            continue
        w.call(fn, f"Rcc::{w.enum_of(fn)}::Div{_g(w.get(x))}")
    if "SYSDIV" in n and w.get("SYSDIV") != 1:
        if w.has("setSystemClockPrescaler"):
            w.call("setSystemClockPrescaler", f"Rcc::{w.enum_of('setSystemClockPrescaler')}::Div{_g(w.get('SYSDIV'))}")
        else:
            w.todo.append("SYSDIV")

    # ---- PLLs
    pll_lines = []
    for pll in _PLLS:
        fn, N = next((f for f in pll["fn"] if w.has(f)), None), first(pll["n"])
        if not N or not w.used(N):
            continue
        if not fn:
            w.todo.append(f"{N}: no modm enable function for this PLL")
            continue
        params = api["functions"][fn]
        # The configuration struct, by reference or by value like on the STM32F2
        struct = next((t for t in re.findall(r"\w+", params) if t in api["structs"]), None)
        fields, out = api["structs"].get(struct, []), []
        M, frac = first(pll["m"]), first(pll["frac"])
        for type, name, *_ in fields:
            key = name.lower()
            if type in api["enums"] and key in ("mul", "div"):
                # The L0/L1 PLL: an enum multiplier, the divider after it as a number
                x = N if key == "mul" else first(["PLLDIV", "PLLDiv"])
                if x:
                    v = _g(w.get(x))
                    out.append(f".{name} = Rcc::{type}::{name}{v}" if type in api["enums"] else f".{name} = {v}")
            elif key == "div" and (x := first(["PLLDIV", "PLLDiv"])):
                out.append(f".{name} = {_g(w.get(x))}")
            elif key == "m" and M:
                out.append(f".M = {_g(w.get(M))}")
            elif key in ("n", "mul"):
                out.append(f".{name} = {_g(w.get(N))}")
            elif key in ("p", "q", "r", "s"):
                if (x := first(pll[key])) and w.used(x) and w.get(x) is not None:
                    out.append(f".{name} = {_g(w.get(x))}")
            elif key == "frac" and frac and w.get(frac):
                out.append(f".Frac = {_g(w.get(frac))}")
            elif key == "range" and M:
                f, ranges = w.freq(M), [e[0] for e in api["enums"].get(type, ())]
                pick = next(
                    (
                        r
                        for r in ranges
                        if (m := re.search(r"MHz(\d+)_(\d+)", r)) and int(m[1]) * 1e6 <= f <= int(m[2]) * 1e6
                    ),
                    None,
                )
                out.append(
                    f".range = Rcc::{type}::{pick}"
                    if pick
                    else f".range = /* TODO {f:g} Hz */ Rcc::{type}::{ranges[0]}"
                )
            elif key == "vcorange" and (
                (M and w.freq(M) < 2e6) or (w.freq(N) < 192e6 and w.nodes[N].get("out_min", 0) >= 150e6)
            ):
                # The narrower VCO range takes a reference of 1 to 2 MHz, the STM32G5 wide one runs from 128 MHz
                low = w.value(type, ["Medium", "Low"])
                out.append(f".vcoRange = Rcc::{type}::{low}")
            elif key == "usbdiv" and "USBPrescaler" in n:
                out.append(f".usbdiv = Rcc::{type}::Div{_g(w.get('USBPrescaler')).replace('.', '_')}")
            elif key == "prediv1" and "HSEDivPLL" in n and w.get("HSEDivPLL") != 1:
                out.append(f".prediv1 = {_g(w.get('HSEDivPLL'))}")
        comment = f"// VCO {unit(w.freq(N)).replace('_', ' ')}"
        struct_name = struct if struct and struct != "PllConfig" else "PllConfig"
        src, src_arg = first(pll["src"]), None
        if "PllSource" in params and src:
            value = w.source_value("PllSource", src)
            default = (api["enums"].get("PllSource") or [[""]])[0][0]
            src_arg = (
                f"Rcc::PllSource::{value}"
                if value
                else f"/* TODO {(w.input(src) or {}).get('from')} */ Rcc::PllSource::{default}"
            )
        var = fn.removeprefix("enable")
        var = var[0].lower() + var[1:]
        # One field per line, the panel and an editor show it without scrolling sideways
        w.consts.append({"comment": comment, "type": struct_name, "name": var, "fields": out})
        pll_lines.append(f"Rcc::{fn}({src_arg + ', ' if src_arg else ''}{var});")
    w.lines += pll_lines

    # ---- the STM32C5 PSI, its frequency and reference are the factor of the PSI node
    if "PSI" in n and w.used("PSI"):
        option = next((d for d in n["PSI"].get("domain", ()) if d["factor"] == w.get("PSI")), None)
        m = option and re.fullmatch(r"PSI_([\d.]+)MHZ_REF_([\d.]+)MHZ", option["macro"])
        source = w.source_value("PsiSource", "PSI_Clock_Mux")
        if m and source and w.has("enablePsi"):
            ref = float(m[2]) * 1e6
            fields = [f".source = Rcc::PsiSource::{source}",
                      f".reference = Rcc::PsiReference::{'Hz32768' if ref < 1e6 else f'MHz{ref / 1e6:g}'}",
                      f".frequency = Rcc::PsiFrequency::MHz{m[1]}"]  # fmt: skip
            if w.used("PSIK"):
                fields.append(f".kernelDivider = Rcc::KernelDivider::Div{_g(w.get('PSIK')).replace('.', '_')}")
            if w.used("PSI_DIV_3"):
                fields.append(".div3 = true")
            w.consts.append({"type": "PsiConfig", "name": "psi", "fields": fields})
            w.call("enablePsi", "psi")
        else:
            w.todo.append(f"PSI {option and option['macro']}")

    # ---- dividers behind a PLL output that modm sets on their own
    for x, fn in _POST_DIVIDERS:
        if x in n and w.used(x) and w.has(fn):
            e = w.enum_of(fn)
            k = _g(w.get(x))
            w.call(fn, f"Rcc::{e}::Div{k}" if e and e != "uint8_t" and e in api["enums"] else k)

    # ---- system clock
    system = first(_SYSTEM_MUX) or _SYSTEM_MUX[0]
    if sys := w.source_value("SystemClockSource", system):
        w.call("enableSystemClock", f"Rcc::SystemClockSource::{sys}")
    else:
        w.todo.append(f"system clock from {(w.input(system) or {}).get('from')}")

    # ---- kernel clock muxes that differ from their reset value
    setters = [
        f for f in api["functions"] if re.fullmatch(r"set\w+Source|setDfsdm\d\w+Clock", f) and f != "setPllSource"
    ]
    handled = {*_SYSTEM_MUX, "PLLSource", "PLL1Source", "PLL2Source", "PLL3Source", "PLL_Clock_Source",
               "PLL1_Clock_Source", "PLL2_Clock_Source", "PSI_Clock_Mux"}  # fmt: skip
    for name, node in n.items():
        if node["kind"] != "mux" or name in handled or len(node["inputs"]) < 2 or not w.used(name):
            continue
        # A prescaler behind the mux that the setter takes too, the STM32G5 ADCDIV
        div = next((o for o in node["outputs"] if n.get(o, {}).get("kind") == "div"), None)
        if w.get(name) == node.get("default") and (not div or w.get(div) == n[div].get("default") or not w.used(div)):
            continue
        setter, input = _pick_setter(w, name, setters), w.input(name)
        if not setter:
            w.todo.append(f"{name} -> {(input or {}).get('from')}: no modm setter")
            continue
        e = w.enum_of(setter)
        if e == "bool":
            # setHsi48ClockSource(bool usePll) on the STM32L0
            w.call(setter, "true" if "PLL" in input["from"].upper() else "false")
            continue
        value = e and w.value(e, candidates(input["from"], input.get("signal", "")))
        if not value and name.startswith("RTC"):
            value = w.value(e, candidates(re.sub(r"RTC.*$", "", input["from"])))
        if not value:
            w.todo.append(f"{setter}({e}::?) for {input['from']}")
            continue
        if name.startswith("MCO"):
            div, e2 = (
                next((o for o in node["outputs"] if n.get(o, {}).get("kind") == "div"), None),
                w.enum_of(setter, 1),
            )
            w.call(setter, f"Rcc::{e}::{value}", *([f"Rcc::{e2}::Div{_g(w.get(div)) if div else 1}"] if e2 else []))
        elif (
            name.startswith("RTC") and "RealTime" in setter and "HSERTCDevisor" in n
            and input["from"] == "HSERTCDevisor" and w.enum_of(setter, 1)
        ):  # fmt: skip
            w.call(setter, f"Rcc::{e}::{value}", _g(w.get("HSERTCDevisor")))
        elif (e2 := w.enum_of(setter, 1)) and e2.endswith("Prescaler"):
            # setAdcClockSource(AdcClockSource, AdcPrescaler) of the STM32G5 and C5
            w.call(
                setter, f"Rcc::{e}::{value}", *([f"Rcc::{e2}::Div{_g(w.get(div))}"] if div and w.get(div) != 1 else [])
            )
        else:
            w.call(setter, f"Rcc::{e}::{value}")
    w.lines.append("Rcc::updateCoreFrequency<Frequency>();")

    # ---- the struct
    core = first(["CpuClockOutput", "CortexSysOutput", "AHBOutput"])
    # [name, node]: SysClk before Frequency, so the core clock can be written as SysClk / 2
    freqs = [("Hse", "HSEOSC")] if w.used("HSEOSC") else []
    freqs += [("SysClk", "SysCLKOutput"), ("Frequency", core or "SysCLKOutput")]
    for k, x in (("Ahb", "AHBOutput"), ("Apb", "APBOutput"), ("Apb1", "APB1Output"), ("Apb2", "APB2Output"),
                 ("Apb3", "APB3Output"), ("Apb4", "APB4Output")):  # fmt: skip
        if x in n:
            freqs.append((k, x))
    used = {u.upper() for u in use} if use else set()
    freqs += [(modm_name(p), p) for p in sorted(x for x in n if n[x]["kind"] == "peripheral" and x.upper() in used)]

    named, frequencies = {}, []
    for k, x in freqs:
        f = w.freq(x)
        frequencies.append((k, (_derive(w, x, named) or unit(f)) if f else None))
        # The name also stands for the nodes it passes through unchanged: APB1Output's prescaler is Apb1 too
        while f and x and x not in named and abs((w.freq(x) or 0) - f) < 0.5:
            named[x] = k
            node = n[x]
            x = None if node["kind"] == "mux" or len(node["inputs"]) != 1 else node["inputs"][0]["from"]
    return {
        "device": device,
        "frequencies": frequencies,
        "pad": max(len(k) for k, _ in freqs),
        "constants": w.consts,
        "calls": w.lines,
        "todos": w.todo,
        "flash": result.get("FLatency", {}).get("setting"),
        "scale": scale,
    }


def generate(tree: dict, device: str, config: dict, result: dict, use, api: dict | None) -> str:
    """
    :param result: `evaluate(tree, config, use)`.
    :param use: the peripherals in use, which get a constant each, None for none.
    :param api: the modm Rcc API of the device, see `modm_api.api_of`.
    :return: C++ source of `namespace Board { struct SystemClock {...}; }`.
    """
    if not api:
        return f"// modm has no Rcc support for {device}"
    data = system_clock(tree, device, config, result, use, api)
    return Environment(trim_blocks=True, lstrip_blocks=True).from_string(_TEMPLATE).render(data)
